# CSD_RATIONALE_BEGIN
# Strategy: natural-delimiter generation with explicit open-span tracking.
# Outside a constrained span, always advance with AppendUnconstrainedStep(prompt, ...).
# A left delimiter is treated as an opening event that switches into span mode.
# Inside a span, use the positive guard helpers.IsComplete(generated) or
# helpers.CanConstrain(generated), then advance with
# AppendConstrainedStep(prompt, ...). A right delimiter is treated as the closing
# event that exits span mode and increments closed_spans.
# Keep a single bounded checkpoint from ordinary reasoning so dead prefixes can
# recover once without turning decoding into rollback-only search.
# When answer_mode begins, continue unconstrained generation until a natural left
# delimiter appears; then finish the constrained span and stop after it closes.
# CSD_RATIONALE_END
phase = "reason"
in_span = False
answer_mode = False
closed_spans = 0
has_checkpoint = False
checkpoint = []
stall_count = 0

# invariant helpers.lm == lm
# invariant helpers.parser == parser
# invariant lm.ValidTokensIdsLogits()
# invariant 0 <= stepsLeft <= maxSteps
# invariant |generated| + stepsLeft <= maxSteps
# decreases stepsLeft
while stepsLeft > 0:
    if in_span:
        if helpers.EndsWithRightDelimiter(generated):
            in_span = False
            closed_spans = closed_spans + 1
            if answer_mode:
                phase = "done"
            else:
                phase = "reason"
        elif helpers.IsComplete(generated) or helpers.CanConstrain(generated):
            generated, stepsLeft = helpers.AppendConstrainedStep(prompt, generated, stepsLeft)
            if helpers.EndsWithRightDelimiter(generated):
                in_span = False
                closed_spans = closed_spans + 1
                if answer_mode:
                    phase = "done"
                else:
                    phase = "reason"
            elif helpers.IsComplete(generated):
                phase = "finalize_span"
            else:
                phase = "span"
        else:
            break
    elif phase == "done":
        break
    elif helpers.IsDead(generated):
        if has_checkpoint:
            generated = helpers.RestoreIfDead(generated, checkpoint)
            has_checkpoint = False
            answer_mode = True
            phase = "answer"
        else:
            break
    elif phase == "finalize_span":
        generated, stepsLeft = helpers.AppendUnconstrainedStep(prompt, generated, stepsLeft)
        if helpers.EndsWithLeftDelimiter(generated):
            in_span = True
            phase = "span"
        elif helpers.EndsWithRightDelimiter(generated):
            closed_spans = closed_spans + 1
            phase = "reason"
        else:
            answer_mode = True
            phase = "answer"
            stall_count = stall_count + 1
    elif answer_mode:
        generated, stepsLeft = helpers.AppendUnconstrainedStep(prompt, generated, stepsLeft)
        if helpers.EndsWithLeftDelimiter(generated):
            in_span = True
            phase = "span"
        elif helpers.EndsWithRightDelimiter(generated):
            closed_spans = closed_spans + 1
            phase = "done"
        else:
            stall_count = stall_count + 1
    elif not has_checkpoint and len(generated) > 0:
        checkpoint = helpers.Checkpoint(generated)
        has_checkpoint = True
        generated, stepsLeft = helpers.AppendUnconstrainedStep(prompt, generated, stepsLeft)
        if helpers.EndsWithLeftDelimiter(generated):
            in_span = True
            phase = "span"
        elif helpers.EndsWithRightDelimiter(generated):
            closed_spans = closed_spans + 1
            phase = "reason"
        else:
            stall_count = stall_count + 1
    elif closed_spans > 0:
        answer_mode = True
        phase = "answer"
        generated, stepsLeft = helpers.AppendUnconstrainedStep(prompt, generated, stepsLeft)
        if helpers.EndsWithLeftDelimiter(generated):
            in_span = True
            phase = "span"
        elif helpers.EndsWithRightDelimiter(generated):
            closed_spans = closed_spans + 1
            phase = "done"
        else:
            stall_count = stall_count + 1
    elif stepsLeft <= helpers.MinStepsToComplete(generated) + 2:
        answer_mode = True
        phase = "answer"
        generated, stepsLeft = helpers.AppendUnconstrainedStep(prompt, generated, stepsLeft)
        if helpers.EndsWithLeftDelimiter(generated):
            in_span = True
            phase = "span"
        elif helpers.EndsWithRightDelimiter(generated):
            closed_spans = closed_spans + 1
            phase = "done"
        else:
            stall_count = stall_count + 1
